import React from "react";

function AboutSources() {
  const sources = [
    {
      name: "WHO (World Health Organization)",
      description: "Co-establishes safety limits and conducts global toxicological evaluations of food additives to protect health.",
      role: "Global Health Directives & Guidance"
    },
    {
      name: "FAO (Food and Agriculture Organization)",
      description: "Works with the WHO on food standards, agricultural safety, and international trade quality guidelines.",
      role: "Agricultural Standards & Safety"
    },
    {
      name: "FDA (Food and Drug Administration)",
      description: "The United States regulatory body that evaluates scientific evidence to license and monitor food ingredients.",
      role: "US Market Regulation & Clearance"
    },
    {
      name: "EFSA (European Food Safety Authority)",
      description: "Provides independent scientific advice and alerts on food additives in Europe, enforcing warning labels.",
      role: "EU Risk Assessments & Mandates"
    },
    {
      name: "Codex Alimentarius",
      description: "A collection of internationally recognized standards, codes of practice, and guidelines relating to food safety.",
      role: "International Food Code Authority"
    }
  ];

  return (
    <div className="about-page">
      <div className="hero-section text-center">
        <h1>Trusted Food Safety Sources</h1>
        <p className="hero-subtitle">
          SAFE BITE relies on safety classifications established by the world's leading food safety authorities.
        </p>
      </div>

      <div className="about-container">
        <div className="info-card card glass text-center">
          <h2>Database Foundation</h2>
          <p className="intro-text">
            To deliver accurate and reliable safety assessments, SAFE BITE matches detected additives against a database compiled from harmonized directives and safety publications from trusted regulatory organizations.
          </p>
        </div>

        <div className="sources-list">
          {sources.map((source, idx) => (
            <div key={idx} className="source-card card glass">
              <div className="source-icon-container">
                <span className="source-icon">🛡️</span>
              </div>
              <div className="source-info">
                <span className="source-badge">{source.role}</span>
                <h3>{source.name}</h3>
                <p>{source.description}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="disclaimer-section card glass">
          <h3>⚠️ Educational Disclaimer</h3>
          <p>
            The assessments provided by SAFE BITE are for educational and informational purposes only. While our data is sourced from reputable scientific and regulatory consensus guidelines, this application does not provide clinical or medical advice. Consumers with severe chemical sensitivities, allergies, or chronic health conditions should consult a certified medical professional or dietitian.
          </p>
        </div>
      </div>
    </div>
  );
}

export default AboutSources;
